nd scoring code retained. Does not count for Singapore national rankings.","importedEntryCount":10,"deferredEntryCount":0,"profilePreflight":[{"id":"90a471f5-bd58-400f-a995-e115951ee1ed","club":"YRAT","name":"Kiitchakhun Somkhanngoen","gender":"Male","handle":"kiitchakhun-somkhanngoen-sw3gwyp","birthYear":2011,"sailNumber":"0","nationality":"THA","sailNumberIlca4":"225917"},{"id":"a5a0ff6f-0576-4a4c-b583-149f6f6d7304","club":"YRAT","name":"Suwaphak Plumjit","gender":"Female","handle":"suwaphak-plumjit-8glzaqs","birthYear":2012,"sailNumber":"0","nationality":"THA","sailNumberIlca4":"222589"},{"id":"87248310-cc92-4094-accd-afe96addeeef","club":"YRAT","name":"Thitiworada Johnjaitrong","gender":"Female","handle":"thitiworada-johnjaitrong-hd6qxkf","birthYear":2010,"sailNumber":"0","nationality":"THA","sailNumberIlca4":"220239"},{"id":"8663b84c-2a24-4fc7-ab61-6598b3ff1fa3","club":"YRAT","name":"Pacharapol Rumvisai","gender":null,"handle":"pacharapol-rumvisai-2xx8xys","birthYear":null,"sailNumber":"0","nationality":"THA","sailNumberIlca4":null},{"id":"f268697a-ceb4-483a-8a53-9c5241f3f0cc","club":"Changi Sailing Club","name":"Reyes Jit Eng Tan","gender":"M","handle":"tan-reyes-jit-eng-fzahuzd","birthYear":2011,"sailNumber":"4712","nationality":"SGP","sailNumberIlca4":"214251"},{"id":"55b6a2bc-3e2e-4ec6-adb3-4e849d8c8380","club":"YRAT","name":"Thanaporn Phokaew","gender":"F","handle":"thanaporn-phokaew-2zbw4z0","birthYear":2011,"sailNumber":"0","nationality":"THA","sailNumberIlca4":"225426"},{"id":"8263464a-01a9-4e55-b8f1-46d96d0173c4","club":"N/A","name":"Karit Phrammanee","gender":null,"handle":"karit-phrammanee-of7ddfd","birthYear":null,"sailNumber":"0","nationality":"SGP","sailNumberIlca4":null},{"id":"f90c9f74-fc6a-4ac4-a2ce-74a584e36038","club":"YRAT/RVYC","name":"Prapada Peeranantapanya","gender":"Female","handle":"prapada-peeranantapanya-rz13syo","birthYear":2012,"sailNumber":"0","nationality":"THA","sailNumberIlca4":"223567"},{"id":"278c69d0-93d3-5d35-8deb-307457689